function maximumGap(nums) {
  const n = nums.length;
  if (n < 2) return 0;
  let low = nums[0];
  let high = nums[0];
  for (const num of nums) {
    low = Math.min(low, num);
    high = Math.max(high, num);
  }
  const size = Math.max(1, Math.floor((high - low) / (n - 1)));
  const count = Math.floor((high - low) / size) + 1;
  const bucketMin = new Array(count).fill(null);
  const bucketMax = new Array(count).fill(null);

  for (const num of nums) {
    const index = Math.floor((num - low) / size);
    if (bucketMin[index] === null || num < bucketMin[index]) {
      bucketMin[index] = num;
    }
    if (bucketMax[index] === null || num > bucketMax[index]) {
      bucketMax[index] = num;
    }
  }

  let best = 0;
  let prevMax = low;
  for (let i = 0; i < count; i++) {
    if (bucketMin[i] === null) continue;
    best = Math.max(best, bucketMin[i] - prevMax);
    prevMax = bucketMax[i];
  }
  return best;
}

